function v9IsTextSubToolSwitch(prevSub, nextSub) {
  if (!nextSub || nextSub.h || !nextSub.icon) return false;
  if (!prevSub || !prevSub.icon) return true;
  return prevSub.icon !== nextSub.icon;
}

function collectV9BridgeTargetPairs(editingRefDrawing) {
  const targets = [];
  const seenIds = new Set();
  const pushPair = (dm, raw) => {
    const live = resolveLiveDrawingInDm(dm, raw);
    if (!live || !live.style) return;
    const id = live.id;
    if (id != null) {
      if (seenIds.has(id)) return;
      seenIds.add(id);
    }
    targets.push({ dm, d: live });
  };
  if (editingRefDrawing) {
    enumerateV9DrawingManagersFromWindow().forEach((dm) => pushPair(dm, editingRefDrawing));
  }
  enumerateV9DrawingManagersFromWindow().forEach((dm) => {
    const tb = dm.toolbar;
    if (tb && tb.currentDrawing) pushPair(dm, tb.currentDrawing);
    if (Array.isArray(dm.selectedDrawings)) {
      dm.selectedDrawings.forEach((x) => pushPair(dm, x));
    }
    if (dm.selectedDrawing) pushPair(dm, dm.selectedDrawing);
  });
  return targets;
}

/** Push V9 `vwapStyle` onto anchored-vwap drawing targets and repaint. */
function v9ApplyVwapStyleToDrawingTargets(vwapStyle, targets) {
  if (!vwapStyle || !Array.isArray(targets) || !targets.length) return;
  try {
    const DASH = { solid: "", dashed: "5,5", dotted: "2,4", dashdot: "7,4,2,4" };
    const SRC_MAP = {
      Close: "close", Open: "open", High: "high", Low: "low",
      "(H+L)/2": "hl2", "(H+L+C)/3": "hlc3", "(O+H+L+C)/4": "ohlc4",
    };
    const CALC_MAP = { "Std Deviation": "standard_deviation", Percentage: "percentage" };
    const chartsToRender = new Set();
    targets.forEach(({ dm, d }) => {
      if (!d || !d.style || d.type !== "anchored-vwap") return;
      const tb = dm.toolbar;
      try { tb && tb.onBeforeUpdate && tb.onBeforeUpdate(d); } catch (_) {}
      d.style.stroke = vwapStyle.vwapColor;
      d.style.color = vwapStyle.vwapColor;
      d.style.strokeWidth = parseInt(vwapStyle.vwapLineWidth, 10) || 2;
      d.style.strokeDasharray = DASH[vwapStyle.vwapLineType] ?? "";
      d.style.source = SRC_MAP[vwapStyle.source] || "hlc3";
      d.style.vwapBandsCalculationMode = CALC_MAP[vwapStyle.bandsCalcMode] || "standard_deviation";
      d.style.showPriceLabel = !!vwapStyle.priceLabels;
      d.style.showTimeLabel = !!vwapStyle.timeLabels;
      [1, 2, 3].forEach((n) => {
        const on = vwapStyle[`band${n}On`];
        const col = vwapStyle[`band${n}Color`];
        const lt = DASH[vwapStyle[`band${n}LineType`]] ?? "2,2";
        const lw = parseInt(vwapStyle[`band${n}LineWidth`], 10) || 1;
        const bgOn = vwapStyle[`bg${n}On`];
        const bgCol = vwapStyle[`bg${n}Color`];
        const multOn = vwapStyle[`mult${n}On`];
        const multVal = parseFloat(vwapStyle[`mult${n}Val`]) || n;
        d.style[`vwapBand${n}Enabled`] = !!on;
        d.style[`vwapUpperBand${n}Enabled`] = !!on;
        d.style[`vwapLowerBand${n}Enabled`] = !!on;
        d.style[`vwapUpperBand${n}Color`] = col;
        d.style[`vwapLowerBand${n}Color`] = col;
        d.style[`vwapUpperBand${n}Type`] = lt;
        d.style[`vwapLowerBand${n}Type`] = lt;
        d.style[`vwapUpperBand${n}Width`] = lw;
        d.style[`vwapLowerBand${n}Width`] = lw;
        d.style[`vwapBand${n}BackgroundEnabled`] = !!bgOn;
        d.style[`vwapBand${n}BackgroundColor`] = bgCol;
        d.style[`vwapBand${n}Multiplier`] = multVal;
        if (multOn !== undefined) d.style[`vwapBand${n}Enabled`] = !!multOn && !!on;
      });
      d._cache = d._cache || {};
      d._cache.vwapPoints = null;
      d._cache.bands = null;
      try {
        if (tb && typeof tb.onUpdate === "function") tb.onUpdate(d);
        else {
          dm.renderDrawing?.(d);
          dm.saveDrawings?.();
        }
      } catch (_) {
        try {
          dm.renderDrawing?.(d);
          dm.saveDrawings?.();
        } catch (_) {}
      }
      if (dm.chart) chartsToRender.add(dm.chart);
    });
    chartsToRender.forEach((ch) => ch.scheduleRender && ch.scheduleRender());
  } catch (err) {
    console.warn("[V9 vwapStyle flush] failed:", err);
  }
}

function v9FlushVwapStyleToChartTargets(vwapStyle, editingRefDrawing) {
  const targets = collectV9BridgeTargetPairs(editingRefDrawing)
    .filter(({ d }) => d && d.type === "anchored-vwap");
  v9ApplyVwapStyleToDrawingTargets(vwapStyle, targets);
}

function v9FlushVwapAnchorCoordToChart(vwapStyle, editingRefDrawing) {
  if (!vwapStyle) return;
  try {
    const chartsToRender = new Set();
    collectV9BridgeTargetPairs(editingRefDrawing).forEach(({ dm, d }) => {
      if (!d || d.type !== "anchored-vwap") return;
      if (!v9ApplyAnchorPointsFromAvStyle(d, vwapStyle)) return;
      const tb = dm.toolbar;
      try { tb && tb.onBeforeUpdate && tb.onBeforeUpdate(d); } catch (_) {}
      try { dm.renderDrawing?.(d); } catch (_) {}
      try { dm.saveDrawings?.(); } catch (_) {}
      if (dm.chart) chartsToRender.add(dm.chart);
    });
    chartsToRender.forEach((ch) => ch.scheduleRender && ch.scheduleRender());
  } catch (err) {
    console.warn("[V9 vwap coord flush] failed:", err);
  }
}

/** Repaint or clear axis price/time labels after style/visibility changes. */
function v9SyncDrawingAxisHighlights(d) {
  if (!d || typeof d.hideAxisHighlights !== "function" || typeof d.showAxisHighlights !== "function") {
    return;
  }
  try {
    if (typeof d.hasVisibleDrawingGeometry === "function" && !d.hasVisibleDrawingGeometry()) {
      d.hideAxisHighlights();
    } else if (d.selected) {
      d.showAxisHighlights();
    }
  } catch (_) {}
}

/** Deep snapshot of a drawing before the V9 settings panel edits it (Cancel restores this). */
function v9CloneDrawingEditState(drawing) {
  if (!drawing) return null;
  const snap = {
    id: drawing.id,
    type: drawing.type,
    text: typeof drawing.text === "string" ? drawing.text : "",
    locked: !!drawing.locked,
    style: drawing.style ? JSON.parse(JSON.stringify(drawing.style)) : {},
  };
  if (drawing.visible === false) snap.visible = false;
  else if (drawing.visible === true) snap.visible = true;
  if (Array.isArray(drawing.levels)) {
    snap.levels = JSON.parse(JSON.stringify(drawing.levels));
  }
  return snap;
}

/** Revert a drawing to its pre-edit snapshot and repaint. */
function v9RestoreDrawingFromEditSnapshot(snap) {
  if (!snap || snap.id == null) return false;
  let restored = false;
  const chartsToRender = new Set();
  enumerateV9DrawingManagersFromWindow().forEach((dm) => {
    const d = resolveLiveDrawingInDm(dm, { id: snap.id });
    if (!d) return;
    restored = true;
    d.style = JSON.parse(JSON.stringify(snap.style || {}));
    d.text = snap.text || "";
    d.locked = !!snap.locked;
    if (snap.visible !== undefined) d.visible = snap.visible;
    if (snap.levels !== undefined) {
      d.levels = JSON.parse(JSON.stringify(snap.levels));
    }
    if (typeof d.setText === "function") {
      try {
        d.setText(d.text);
      } catch (_) {}
    }
    const tb = dm.toolbar;
    try {
      if (tb && typeof tb.onBeforeUpdate === "function") tb.onBeforeUpdate(d);
    } catch (_) {}
    try {
      if (tb && typeof tb.onUpdate === "function") tb.onUpdate(d);
      else if (typeof dm.renderDrawing === "function") dm.renderDrawing(d);
    } catch (_) {
      try {
        dm.renderDrawing?.(d);
      } catch (_) {}
    }
    v9SyncDrawingAxisHighlights(d);
    try {
      if (typeof dm.saveDrawings === "function") dm.saveDrawings();
    } catch (_) {}
    if (dm.chart) chartsToRender.add(dm.chart);
  });
  chartsToRender.forEach((c) => {
    if (c && typeof c.scheduleRender === "function") c.scheduleRender();
  });
  return restored;
}

/**
 * Apply full `tlStyle` → selected/edited drawings immediately (all TlChk toggles, first click).
 * Does not re-run the layout bridge (avoids stale-state revert on checkbox toggles).
 */
function v9FlushTlStyleToChartTargets(tlStyle, opts = {}) {
  if (!tlStyle) return;
  const editingRefDrawing = opts.editingRefDrawing ?? null;
  const resolveLegacyTool = opts.resolveLegacyTool;
  const colorOnly = !!opts.colorOnly;
  // Mid-placement color picks must update the temp preview only — not mutate finished drawings.
  if (colorOnly && !editingRefDrawing && v9AnyDrawingManagerPlacing()) {
    return;
  }
  const editSess = editingRefDrawing ? { drawing: editingRefDrawing } : null;
  const legacyTool = v9ResolveLegacyToolForStyleBridge(resolveLegacyTool, editSess);
  const chartsToRender = new Set();
  try {
    const pairs = collectV9BridgeTargetPairs(editingRefDrawing);
    pairs.forEach(({ dm, d }) => {
      if (!d || !d.style) return;
      const effectiveTool = v9EffectiveLegacyToolForDrawing(d, legacyTool, editSess);
      if (!v9ShouldApplyTlStylePatch(d, effectiveTool, editSess, dm)) return;
      if (!v9StyleBridgeAppliesToDrawing(d, editSess)) return;
      const stylePatch = colorOnly
        ? v9BuildColorOnlyPatchFromPickerKey(
            opts.pickerKey,
            tlStyle,
            effectiveTool || d.type,
          )
        : v9BuildLegacyStylePatchFromTlStyle(tlStyle, effectiveTool);
      const tb = dm.toolbar;
      try {
        if (tb && typeof tb.onBeforeUpdate === "function") tb.onBeforeUpdate(d);
      } catch (_) {}
      Object.assign(d.style, stylePatch);
      if (colorOnly) {
        v9ApplyPickerColorOnlyExtras(d, tlStyle, opts.pickerKey);
      } else {
        v9ApplyTlStyleExtrasToDrawing(d, tlStyle, dm);
      }
      try {
        if (tb && typeof tb.onUpdate === "function") tb.onUpdate(d);
        else if (typeof dm.renderDrawing === "function") dm.renderDrawing(d);
      } catch (_) {
        try {
          dm.renderDrawing?.(d);
        } catch (_) {}
      }
      v9SyncDrawingAxisHighlights(d);
      if (dm.chart) chartsToRender.add(dm.chart);
    });
    chartsToRender.forEach((c) => {
      if (c && typeof c.scheduleRender === "function") c.scheduleRender();
    });
  } catch (err) {
    console.warn("[V9 tlStyle flush] failed:", err);
  }
}

/** Color-picker keys that mutate `tlStyle` and should repaint the selected drawing immediately. */
function v9CpPickerKeyFlushesTlStyle(key) {
  if (!key || typeof key !== "string") return false;
  if (
    key === "gotoNewColor" ||
    key.startsWith("vwap_") ||
    key.startsWith("vp_") ||
    key.startsWith("av_") ||
    key.startsWith("rr_") ||
    key.startsWith("ind-") ||
    key.startsWith("txt")
  ) {
    return false;
  }
  const direct = new Set([
    "tlLineColor", "tlBgColor", "tlMidLineColor", "tlTextColor", "tlLabelColor",
    "tlLabelBgColor", "tlBorderColor", "tlFlatChPriceColor", "fibTrendColor", "fibGridColor",
    "regUpperBg", "regLowerBg",
    "pfMedianColor", "pfBgColor",
  ]);
  if (direct.has(key)) return true;
  return /^(chLine|regLine|pfLevel|fibLevel|fibTzLevel|fibFanTimeLevel|gannPrice|gannTime|gannGrid|gannFanLv|gannArc)-\d+$/.test(key);
}

function v9CpPickerKeyFlushesTxtStyle(key) {
  return ["txtTextColor", "txtBgColor", "txtBorderColor", "txtLineColor", "pinLabelColor"].includes(key);
}

function v9CpPickerKeyFlushesVwapStyle(key) {
  return typeof key === "string" && key.startsWith("vwap_");
}

/** Apply `txtStyle` → selected text drawings immediately (color picker drag / hex). */
function v9FlushTxtStyleToChartTargets(txtStyle, opts = {}) {
  if (!txtStyle) return;
  const editingRefDrawing = opts.editingRefDrawing ?? null;
  const armedLegacyTool = opts.armedLegacyTool ?? null;
  const editSess = editingRefDrawing ? { drawing: editingRefDrawing } : null;
  const chartsToRender = new Set();
  try {
    collectV9BridgeTargetPairs(editingRefDrawing).forEach(({ dm, d }) => {
      if (!d || !d.style) return;
      if (v9DrawingTypeToPanelGroup(d.type) !== "text") return;
      if (!v9StyleBridgeAppliesToDrawing(d, editSess)) return;
      if (!v9ShouldApplyTxtStylePatch(d, armedLegacyTool, editSess, dm, opts.txtStyleOwnerType ?? null)) return;
      const tb = dm.toolbar;
      try {
        if (tb && typeof tb.onBeforeUpdate === "function") tb.onBeforeUpdate(d);
      } catch (_) {}
      v9ApplyTxtStyleToDrawing(d, txtStyle, { applyContent: opts.applyContent === true });
      const isInlineEditing = dm._textInlineEditDrawing === d || d._inlineTextEditing || d._pendingAutoInlineEdit;
      if (isInlineEditing) {
        const helpers = typeof window !== "undefined" ? window.DrawingTextHelpers : null;
        if (helpers && typeof helpers.scheduleTextAnnotationLiveRender === "function") {
          helpers.scheduleTextAnnotationLiveRender(d);
        } else if (typeof dm.scheduleRenderDrawing === "function") {
          dm.scheduleRenderDrawing(d);
        } else {
          try { dm.renderDrawing?.(d); } catch (_) {}
        }
        if (dm.chart) chartsToRender.add(dm.chart);
        return;
      }
      if (tb && typeof tb.onUpdate === "function") {
        try {
          tb.onUpdate(d);
        } catch (_) {
          try {
            dm.renderDrawing?.(d);
          } catch (_) {}
        }
      } else {
        try {
          dm.renderDrawing?.(d);
        } catch (_) {}
      }
      v9SyncDrawingAxisHighlights(d);
      if (dm.chart) chartsToRender.add(dm.chart);
    });
    chartsToRender.forEach((c) => {
      if (c && typeof c.scheduleRender === "function") c.scheduleRender();
    });
  } catch (err) {
    console.warn("[V9 txtStyle flush] failed:", err);
  }
}

const V9_LEGACY_DASH_STRING_TO_LINE_TYPE = (() => {
  const map = {};
  Object.entries({ solid: '', dashed: '10,6', dotted: '2,2', dashdot: '8,4,2,4' }).forEach(([k, v]) => { map[v] = k; });
  map['0'] = 'solid';
  map['5,5'] = 'dashed';
  map['7,4'] = 'dashed';
  map['4,4'] = 'dashed';
  map['2,4'] = 'dotted';
  map['1,3'] = 'dotted';
  return map;
})();

/** V9 line type → chart.js `stroke-dasharray` for parallel-channel level lines. */
const V9_LINE_TYPE_TO_LEGACY_DASH = { solid: '', dashed: '5,5', dotted: '2,4', dashdot: '7,4,2,4', bold: '' };

/** Map V9 line style + width → dash/width (bold/solid = solid dash only; width from THICKNESS). */
function v9LineDashAndWidthFromType(type, widthRaw, dashMap = V9_LINE_TYPE_TO_LEGACY_DASH) {
  const t = type || "solid";
  const parsed = parseInt(String(widthRaw), 10);
  const width = Number.isFinite(parsed) && parsed > 0 ? parsed : 2;
  const dash = t === "bold" || t === "solid"
    ? ""
    : (dashMap[t] !== undefined ? dashMap[t] : "");
  return { dash, width };
}

/** Middle line on parallel channel is adjustable only between these levels. */
const V9_PARALLEL_CHANNEL_MIDDLE_MIN = 0.25;
const V9_PARALLEL_CHANNEL_MIDDLE_MAX = 0.75;

/** Default parallel-channel level rows (0/1 rails + 0.25/0.75 middle bounds). */
function v9DefaultParallelChannelChLines(strokeColor) {
  const base = strokeColor || "#2962FF";
  const aux = "#1e3a5f";
  return [
    { on: true, value: "0", color: base, type: "solid", width: "2" },
    { on: false, value: "0.25", color: aux, type: "solid", width: "2" },
    { on: true, value: "0.5", color: base, type: "dashed", width: "1", middle: true },
    { on: false, value: "0.75", color: aux, type: "solid", width: "2" },
    { on: true, value: "1", color: base, type: "solid", width: "2" },
  ].map((row) => ({ ...row }));
}

function v9ParallelChannelLevelSortKey(ln) {
  const v = parseFloat(String(ln?.value ?? "").replace(/,/g, ""));
  return Number.isFinite(v) ? v : 0;
}

/** Sort level rows by numeric value (stable) — internal storage order. */
function v9SortParallelChannelChLines(chLines) {
  if (!Array.isArray(chLines) || chLines.length < 2) {
    return Array.isArray(chLines) ? chLines.map((row) => ({ ...row })) : [];
  }
  return chLines
    .map((row, i) => ({ row: { ...row }, i }))
    .sort((a, b) => {
      const d = v9ParallelChannelLevelSortKey(a.row) - v9ParallelChannelLevelSortKey(b.row);
      return d !== 0 ? d : a.i - b.i;
    })
    .map(({ row }) => row);
}

function v9ParallelChannelRowIsUpper(row) {
  const v = parseFloat(String(row?.value ?? "").replace(/,/g, ""));
  return Number.isFinite(v) && Math.abs(v - 1) < 1e-6;
}

function v9ParallelChannelRowIsLower(row) {
  const v = parseFloat(String(row?.value ?? "").replace(/,/g, ""));
  return Number.isFinite(v) && Math.abs(v) < 1e-6;
}

/** UI row order: Upper → Middle → aux levels → Lower. */
function v9ParallelChannelUiRowOrder(chLines, { includeMiddle = true } = {}) {
  if (!Array.isArray(chLines) || !chLines.length) return [];
  const midIdx = v9ParallelChannelMidLineRowIndex(chLines);
  const entries = chLines.map((row, i) => ({ row, i }));
  const upper = entries.find((e) => v9ParallelChannelRowIsUpper(e.row));
  const lower = entries.find((e) => v9ParallelChannelRowIsLower(e.row));
  const middle = midIdx >= 0 ? entries[midIdx] : null;
  const aux = entries
    .filter((e) => e.i !== midIdx && e.i !== upper?.i && e.i !== lower?.i)
    .sort((a, b) => v9ParallelChannelLevelSortKey(a.row) - v9ParallelChannelLevelSortKey(b.row));
  const ordered = [];
  if (upper) ordered.push(upper);
  if (includeMiddle && middle) ordered.push(middle);
  ordered.push(...aux);
  if (lower) ordered.push(lower);
  return ordered;
}

/** Panel-safe `chLines` — never empty for parallel-channel UI. */
function v9ResolveParallelChannelChLines(tlStyle, drawing) {
  let rows;
  if (Array.isArray(tlStyle?.chLines) && tlStyle.chLines.length > 0) {
    rows = tlStyle.chLines;
  } else {
    const stroke = drawing?.style?.stroke || drawing?.style?.color || tlStyle?.lineColor;
    if (Array.isArray(drawing?.levels) && drawing.levels.length > 0) {
      const fromLv = v9ParallelLevelsToChLines(drawing.levels);
      rows = fromLv && fromLv.length ? fromLv : v9DefaultParallelChannelChLines(stroke);
    } else {
      rows = v9DefaultParallelChannelChLines(stroke);
    }
  }
  return v9SortParallelChannelChLines(rows);
}

/** Pick the adjustable middle row (not 0/1 boundary or 0.25/0.75 aux rails). */
function v9ParallelChannelMiddleLevelIndexFromRows(rows) {
  if (!Array.isArray(rows) || !rows.length) return -1;
  const flagged = rows.findIndex((ln) => ln && ln.middle === true);
  if (flagged >= 0) return flagged;
  for (let i = 0; i < rows.length; i++) {
    const v = parseFloat(String(rows[i]?.value ?? "").replace(/,/g, ""));
    if (!Number.isFinite(v) || v <= 0.001 || v >= 0.999) continue;
    if (Math.abs(v - 0.25) < 1e-6 || Math.abs(v - 0.75) < 1e-6) continue;
    return i;
  }
  const halfIdx = rows.findIndex((ln) => {
    const v = parseFloat(String(ln?.value ?? "").replace(/,/g, ""));
    return Number.isFinite(v) && Math.abs(v - 0.5) < 1e-6;
  });
  if (halfIdx >= 0) return halfIdx;
  return v9ParallelChannelMidLineRowIndex(rows);
}

/** `drawing.levels` (parallel-channel) ↔ Settings panel `tlStyle.chLines`. */
function v9ParallelLevelsToChLines(levels) {
  if (!Array.isArray(levels) || !levels.length) return undefined;
  const rows = levels.map((lv) => {
    const raw = (lv.lineType != null && lv.lineType !== '') ? String(lv.lineType).replace(/\s+/g, '') : '';
    let lineType = V9_LEGACY_DASH_STRING_TO_LINE_TYPE[raw];
    if (lineType == null) {
      if (raw === '0' || raw === 'none') lineType = 'solid';
      else lineType = raw ? 'dashed' : 'solid';
    }
    const w = lv.lineWidth != null ? String(parseInt(lv.lineWidth, 10) || 2) : '2';
    const numVal = typeof lv.value === 'number' ? lv.value : parseFloat(lv.value);
    const valueStr = Number.isFinite(numVal)
      ? (Number.isInteger(numVal) ? String(numVal) : numVal.toFixed(4).replace(/\.?0+$/, '') || '0')
      : String(lv.value ?? '0');
    return {
      on: lv.enabled !== false,
      value: valueStr,
      color: lv.color || '#2962FF',
      type: lineType,
      width: w,
    };
  });
  const midIdx = v9ParallelChannelMiddleLevelIndexFromRows(rows);
  return rows.map((row, i) => ({
    ...row,
    middle: i === midIdx,
  }));
}

function v9ParallelChannelMidLineRowIndex(chLines) {
  return v9ParallelChannelMiddleLevelIndexFromRows(chLines);
}

function v9IsPartialChannelLevelValue(val) {
  const s = String(val ?? "").trim();
  return !s || s === "-" || s.endsWith(".");
}

function v9ClampParallelChannelMiddleValue(raw) {
  const v = parseFloat(String(raw));
  if (!Number.isFinite(v)) return String(raw ?? "0.5");
  const clamped = Math.min(
    V9_PARALLEL_CHANNEL_MIDDLE_MAX,
    Math.max(V9_PARALLEL_CHANNEL_MIDDLE_MIN, Math.round(v * 100) / 100),
  );
  return clamped.toFixed(2);
}

/** Style-tab label for a parallel-channel level row (middle line has its own section). */
function v9ParallelChannelStyleRowLabel(filteredIdx, filteredLen, ln) {
  const v = parseFloat(String(ln?.value ?? "").replace(/,/g, ""));
  if (Number.isFinite(v)) {
    if (Math.abs(v) < 0.0001) return "Lower";
    if (Math.abs(v - 1) < 0.0001) return "Upper";
    return Number.isInteger(v) ? String(v) : String(v);
  }
  return v9ParallelChannelAuxLevelLabel(ln, filteredIdx);
}

function v9ParallelChannelAuxLevelLabel(ln, fallbackIdx = 0) {
  const raw = ln?.value;
  if (raw != null && String(raw).trim() !== "") {
    const v = parseFloat(String(raw).replace(/,/g, ""));
    if (Number.isFinite(v)) {
      return Number.isInteger(v) ? String(v) : String(v);
    }
    return String(raw);
  }
  return `Level ${fallbackIdx + 1}`;
}

/** Input-tab label — Lower (0), Middle (0.5), Upper (1); aux rows show their value. */
function v9ParallelChannelInputRowLabel(ln, idx, lines, midIdx) {
  if (idx === midIdx) return "Middle";
  const v = parseFloat(String(ln?.value ?? "").replace(/,/g, ""));
  if (Number.isFinite(v)) {
    if (Math.abs(v) < 0.0001) return "Lower";
    if (Math.abs(v - 1) < 0.0001) return "Upper";
  }
  return v9ParallelChannelAuxLevelLabel(ln, idx);
}

/** Style-tab label for a regression-channel line row (middle / upper / lower). */
function v9RegressionChannelRowLabel(rowIdx, ln) {
  const existing = ln?.label != null ? String(ln.label).trim() : "";
  if (existing) return existing;
  if (rowIdx === 0) return "Middle Line";
  if (rowIdx === 1) return "Upper";
  if (rowIdx === 2) return "Lower";
  return `Line ${rowIdx + 1}`;
}

/** UI row order for regression channel Style tab: Upper → Middle → Lower. */
