  // Navigation integrity badge — fixed-width .ohlc-nav-badge-slot after .ohlc-stats-flow; #ohlc-info width set in chart.js.
  useEffect(() => {
    let cancelled = false;
    const sync = () => {
      if (cancelled) return;
      const rs = getReplaySystem();
      const replayOn = !!(rs && rs.isActive);
      const allowBack =
        rs && typeof rs.isBackNavigationAllowed === "function"
          ? rs.isBackNavigationAllowed()
          : true;
      const rbBlocked = !!(rs && rs.isActive && typeof rs.isBackNavigationAllowed === "function" && !rs.isBackNavigationAllowed());
      setReplayRollbackBlocked((prev) => (prev === rbBlocked ? prev : rbBlocked));
      setReplayOhlcBadgeVisible((prev) => (prev === replayOn ? prev : replayOn));
      const badge = document.getElementById("navIntegrityBadge");
      const tooltip = document.getElementById("navBadgeTooltip");
      if (!badge) return;
      const navStateColor = allowBack ? "#22c55e" : "#ef4444";
      badge.style.color = navStateColor;
      const navSvg = badge.querySelector(".nav-badge-go-back");
      if (navSvg) navSvg.style.setProperty("color", navStateColor, "important");
      badge.classList.toggle("enabled", allowBack);
      badge.classList.toggle("disabled", !allowBack);
      if (tooltip) {
        tooltip.style.removeProperty("color");
        tooltip.replaceChildren();
        const s = document.createElement("strong");
        s.textContent = allowBack ? "You can navigate" : "You cannot navigate";
        tooltip.appendChild(s);
      }
      if (tooltip && badge && (badge.matches(":hover") || badge.classList.contains("show-tooltip"))) {
        const stack = typeof window !== "undefined" && window.__TalariaToastStack;
        if (stack && typeof stack.anchorBottomPx === "function") {
          const b = stack.anchorBottomPx();
          if (Number.isFinite(b)) tooltip.style.bottom = `${Math.round(b)}px`;
        }
      }
    };
    sync();
    const id = setInterval(sync, 300);
    const onDocClick = () => {
      const b = document.getElementById("navIntegrityBadge");
      if (b) b.classList.remove("show-tooltip");
    };
    document.addEventListener("click", onDocClick);
    return () => {
      cancelled = true;
      clearInterval(id);
      document.removeEventListener("click", onDocClick);
    };
  }, []);

