                      border:`2px solid ${c.sf}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:"default",
                      boxShadow:swHov==="prof-avatar-btn"||swHov==="prof-avatar-btn_dn"?`0 0 8px ${c.acG}`:`0 1px 4px ${c.acG}`,
